function routeNeed(need) {
  if (need.changes === 'hourly' || need.cite) return 'rag';
  if (need.stable && (need.style || need.skill)) return 'finetune-or-prompt';
  if (need.small && !need.fresh) return 'bigger-prompt';
  return 'rag';
}
const cases = [
  [{ changes: 'hourly', cite: true }, 'rag'],
  [{ stable: true, style: true }, 'finetune-or-prompt'],
  [{ stable: true, skill: true }, 'finetune-or-prompt'],
  [{ small: true, fresh: false }, 'bigger-prompt'],
];
let pass = 0;
for (const [need, expected] of cases) {
  const got = routeNeed(need);
  if (got === expected) pass++;
  else console.log('MISS ' + JSON.stringify(need) + ' -> ' + got);
}
console.log(pass + '/' + cases.length + ' needs routed');

